    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def sget(key, default=None):
        try:
            return observation.get(key, default)
        except Exception:
            return default

    def step_towards(a, b):
        ax, ay = a
        bx, by = b
        dx = 0 if bx == ax else (1 if bx > ax else -1)
        dy = 0 if by == ay else (1 if by > ay else -1)
        return [dx, dy]

    def step_away(a, b):
        ax, ay = a
        bx, by = b
        dx = 0 if bx == ax else (-1 if bx > ax else 1)
        dy = 0 if by == ay else (-1 if by > ay else 1)
        return [dx, dy]

    def best_nearest(items, here):
        best = None
        best_d = None
        hx, hy = here
        for item in items:
            x, y = pos(item, None)
            if x is None:
                continue
            d = abs(x - hx) + abs(y - hy)
            if best is None or d < best_d:
                best = (x, y)
                best_d = d
        return best

    def farthest_corner(here, w, h):
        hx, hy = here
        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        best = corners[0]
        best_d = -1
        for c in corners:
            d = abs(c[0] - hx) + abs(c[1] - hy)
            if d > best_d:
                best = c
                best_d = d
        return best

    env = sget("environment_name", "resource_collection")
    sx, sy = pos(sget("self_position"), (0, 0))
    ox, oy = pos(sget("opponent_position"), (sx, sy))
    here = (sx, sy)
    w = sget("grid_width", 11)
    h = sget("grid_height", 11)

    if env == "pursuit_evasion":
        role = sget("self_role", "pursuer")
        if role == "pursuer":
            return step_towards(here, (ox, oy))
