        away = step_away(here, (ox, oy))
        if away != [0, 0]:
            return away
        return step_towards(here, target)

    if env == "territory_control":
        targets = sget("unclaimed_cells") or sget("opponent_territory") or sget("neutral_cells") or []
        target = best_nearest(targets, here)
        if target is None:
            if isinstance(w, int) and isinstance(h, int) and w > 0 and h > 0:
                target = (w // 2, h // 2)
            else:
                target = (ox, oy)
        return step_towards(here, target)

    resources = sget("resources") or sget("resource_cells") or []
    target = best_nearest(resources, here)
    if target is not None:
        return step_towards(here, target)

    return step_towards(here, (ox, oy))

